import { axiosInstance } from '@dwp-frontend/shared-utils/axios-instance';
import { productSurfaceReadScopeConfig } from '@dwp-frontend/shared-utils/api/product-surface-read-scope';

import type { ApiResponse, HrPayWorkspace } from '@dwp-frontend/shared-utils';

export const HRIS_PAYROLL_WORKSPACE_API_PATH = '/api/people/v1/hr/pay' as const;

export async function getHrisPayrollWorkspace(
  contextScopeKey: string | undefined,
  signal: AbortSignal
): Promise<HrPayWorkspace> {
  const response = await axiosInstance.get<ApiResponse<HrPayWorkspace>>(
    HRIS_PAYROLL_WORKSPACE_API_PATH,
    productSurfaceReadScopeConfig(contextScopeKey, signal)
  );
  return response.data.data;
}

import { afterEach, describe, expect, it, vi } from 'vitest';
import { resetCsrfToken } from '@dwp-frontend/shared-utils/axios-instance';
import { HttpTransportError } from '@dwp-frontend/shared-utils';

import { getHrisPayrollWorkspace } from './payroll-api';

function jsonResponse(data: unknown): Response {
  return {
    ok: true,
    status: 200,
    text: async () => JSON.stringify({ data }),
  } as Response;
}

describe('getHrisPayrollWorkspace', () => {
  afterEach(() => {
    resetCsrfToken();
    vi.unstubAllGlobals();
  });

  it('binds the personal HR scope to the Gateway GET', async () => {
    const response = { employee: { personId: 'person-1' }, statements: [] };
    const fetchMock = vi.fn().mockResolvedValue(jsonResponse(response));
    vi.stubGlobal('fetch', fetchMock);
    const controller = new AbortController();

    await expect(
      getHrisPayrollWorkspace('scope:hcm/personal-pay', controller.signal)
    ).resolves.toEqual(response);

    expect(fetchMock).toHaveBeenCalledOnce();
    expect(fetchMock.mock.calls[0]?.[0]).toBe(
      '/api/people/v1/hr/pay?contextScopeKey=scope%3Ahcm%2Fpersonal-pay'
    );
    expect((fetchMock.mock.calls[0]?.[1] as RequestInit).signal).toBeInstanceOf(AbortSignal);
  });

  it('propagates React Query cancellation to the active Gateway request', async () => {
    const fetchMock = vi.fn(
      (_url: string, init?: RequestInit) =>
        new Promise<Response>((_resolve, reject) => {
          init?.signal?.addEventListener('abort', () => {
            reject(new DOMException('The operation was aborted.', 'AbortError'));
          });
        })
    );
    vi.stubGlobal('fetch', fetchMock);
    const controller = new AbortController();

    const request = getHrisPayrollWorkspace('scope:hcm/personal-pay', controller.signal).then(
      () => undefined,
      (error: unknown) => error
    );
    controller.abort('scope-changed');

    await expect(request).resolves.toEqual(expect.any(HttpTransportError));
    await expect(request).resolves.toMatchObject({ reason: 'ABORT' });
    expect(fetchMock.mock.calls[0]?.[1]?.signal?.aborted).toBe(true);
  });
});

import { useQuery } from '@tanstack/react-query';

import { useProductSurfaceRequestScope } from '../../../../components/use-product-surface-request-scope';
import { getHrisPayrollWorkspace } from '../api/payroll-api';
import { buildPayrollSelfServiceModel } from '../model/payroll-self-service-model';

export function useHrisPayrollWorkspace() {
  const requestScope = useProductSurfaceRequestScope({
    productKey: 'hcm',
    surfaceKey: 'hcm.personal',
  });
  const query = useQuery({
    queryKey: ['hcm', 'pay', ...requestScope.cacheKey],
    queryFn: async ({ signal }) => {
      const source = await getHrisPayrollWorkspace(requestScope.contextScopeKey, signal);
      return buildPayrollSelfServiceModel(source);
    },
    enabled: requestScope.ready,
    meta: requestScope.queryMeta,
    staleTime: 60_000,
  });

  return {
    ready: requestScope.ready,
    authorityKey: JSON.stringify(requestScope.cacheKey),
    model: query.data,
    isLoading: query.isLoading,
    isFetching: query.isFetching,
    error: query.error,
    retry: () => void query.refetch(),
  };
}

// Domain projection inputs deliberately exclude the employee and monetary transport payload.
// API/hook adapters may supply structurally compatible source values; UI only receives the model.
export type PayrollDataOrigin = 'SOURCE' | 'MANUAL' | 'REFERENCE' | 'MIXED' | 'NONE' | 'UNKNOWN';

export type PayrollCycleModel = {
  payCycleId: string;
  name: string;
  periodStart: string;
  periodEnd: string;
  payDate: string;
  status: string;
  timeValidated: boolean;
  absenceValidated: boolean;
  sourceConfirmed: boolean;
  dataOrigin: PayrollDataOrigin;
};

export type PayrollStatementSource = {
  statementId: string;
  periodLabel: string;
  availabilityState: string;
  publishedAt?: string | null;
  downloadable: boolean;
};

export type PayrollWorkspaceSource = {
  nextCycle?: PayrollCycleModel | null;
  statements: PayrollStatementSource[];
  monetaryDataRedacted: boolean;
};

export const HRIS_PAYROLL_ROUTE = '/hr/pay' as const;

export const PAYROLL_SELF_SERVICE_CONTRACT = {
  route: HRIS_PAYROLL_ROUTE,
  primaryUser: 'EMPLOYEE',
  operationalQuestion: 'Which pay statements has the secure payroll source made available to me?',
  primaryAction: 'DOWNLOAD_AVAILABLE_SOURCE_STATEMENT',
  pageArchetype: 'LIST_DETAIL',
  calculatesPayroll: false,
  confirmsPayroll: false,
  initiatesPayment: false,
  displaysMonetaryValues: false,
} as const;

export type PayrollStatementAvailability =
  'AVAILABLE' | 'PENDING' | 'WITHHELD' | 'RETIRED' | 'UNKNOWN';

export type PayrollStatementAccess = 'DOWNLOADABLE' | 'DOWNLOAD_NOT_GRANTED' | 'NOT_AVAILABLE';

export type PayrollStatementModel = {
  statementId: string;
  periodLabel: string;
  availability: PayrollStatementAvailability;
  sourceAvailability: string;
  publishedAt: string | null;
  sourceDownloadable: boolean;
  access: PayrollStatementAccess;
};

export type PayrollSelfServiceModel = {
  dataOrigin: PayrollDataOrigin;
  containsReferenceData: boolean;
  sourceConfirmed: boolean | null;
  monetaryDataRedacted: boolean;
  nextCycle: PayrollCycleModel | null | undefined;
  statements: PayrollStatementModel[];
  empty: boolean;
};

const KNOWN_AVAILABILITY = new Set<PayrollStatementAvailability>([
  'AVAILABLE',
  'PENDING',
  'WITHHELD',
  'RETIRED',
]);

export function normalizePayrollStatementAvailability(
  availabilityState: string
): PayrollStatementAvailability {
  const normalized = availabilityState.trim().toUpperCase();
  return KNOWN_AVAILABILITY.has(normalized as PayrollStatementAvailability)
    ? (normalized as PayrollStatementAvailability)
    : 'UNKNOWN';
}

export function toPayrollStatementModel(statement: PayrollStatementSource): PayrollStatementModel {
  const availability = normalizePayrollStatementAvailability(statement.availabilityState);
  const sourceDownloadable = availability === 'AVAILABLE' && statement.downloadable;
  const access: PayrollStatementAccess =
    availability !== 'AVAILABLE'
      ? 'NOT_AVAILABLE'
      : sourceDownloadable
        ? 'DOWNLOADABLE'
        : 'DOWNLOAD_NOT_GRANTED';

  return {
    statementId: statement.statementId,
    periodLabel: statement.periodLabel,
    availability,
    sourceAvailability: statement.availabilityState || 'UNKNOWN',
    publishedAt: statement.publishedAt ?? null,
    sourceDownloadable,
    access,
  };
}

export function buildPayrollSelfServiceModel(
  workspace: PayrollWorkspaceSource
): PayrollSelfServiceModel {
  const dataOrigin = workspace.nextCycle?.dataOrigin ?? 'NONE';
  const statements = workspace.statements.map(toPayrollStatementModel);

  return {
    dataOrigin,
    containsReferenceData: dataOrigin === 'REFERENCE' || dataOrigin === 'MIXED',
    sourceConfirmed: workspace.nextCycle?.sourceConfirmed ?? null,
    monetaryDataRedacted: workspace.monetaryDataRedacted,
    nextCycle: workspace.nextCycle
      ? {
          payCycleId: workspace.nextCycle.payCycleId,
          name: workspace.nextCycle.name,
          periodStart: workspace.nextCycle.periodStart,
          periodEnd: workspace.nextCycle.periodEnd,
          payDate: workspace.nextCycle.payDate,
          status: workspace.nextCycle.status,
          timeValidated: workspace.nextCycle.timeValidated,
          absenceValidated: workspace.nextCycle.absenceValidated,
          sourceConfirmed: workspace.nextCycle.sourceConfirmed,
          dataOrigin: workspace.nextCycle.dataOrigin,
        }
      : workspace.nextCycle,
    statements,
    empty: !workspace.nextCycle && statements.length === 0,
  };
}

import { describe, expect, it } from 'vitest';

import {
  PAYROLL_SELF_SERVICE_CONTRACT,
  buildPayrollSelfServiceModel,
  normalizePayrollStatementAvailability,
  toPayrollStatementModel,
} from './payroll-self-service-model';

import type { PayrollStatementSource, PayrollWorkspaceSource } from './payroll-self-service-model';

function workspace(overrides: Partial<PayrollWorkspaceSource> = {}): PayrollWorkspaceSource {
  return {
    nextCycle: {
      payCycleId: 'cycle-1',
      name: 'September payroll',
      periodStart: '2026-09-01',
      periodEnd: '2026-09-30',
      payDate: '2026-09-25',
      status: 'OPEN',
      timeValidated: true,
      absenceValidated: false,
      sourceConfirmed: true,
      dataOrigin: 'SOURCE',
    },
    statements: [],
    monetaryDataRedacted: true,
    ...overrides,
  };
}

function statement(overrides: Partial<PayrollStatementSource> = {}): PayrollStatementSource {
  return {
    statementId: 'statement-1',
    periodLabel: 'August 2026',
    availabilityState: 'AVAILABLE',
    publishedAt: '2026-08-25T00:00:00Z',
    downloadable: true,
    ...overrides,
  };
}

describe('PAYROLL_SELF_SERVICE_CONTRACT', () => {
  it('keeps the personal pay anchor outside payroll calculation and payment execution', () => {
    expect(PAYROLL_SELF_SERVICE_CONTRACT).toMatchObject({
      route: '/hr/pay',
      primaryUser: 'EMPLOYEE',
      primaryAction: 'DOWNLOAD_AVAILABLE_SOURCE_STATEMENT',
      calculatesPayroll: false,
      confirmsPayroll: false,
      initiatesPayment: false,
      displaysMonetaryValues: false,
    });
  });
});

describe('buildPayrollSelfServiceModel', () => {
  it('exposes reference provenance, source confirmation and redaction without inventing values', () => {
    const model = buildPayrollSelfServiceModel(
      workspace({
        nextCycle: {
          ...workspace().nextCycle!,
          dataOrigin: 'REFERENCE',
          sourceConfirmed: false,
        },
        monetaryDataRedacted: false,
      })
    );

    expect(model).toMatchObject({
      dataOrigin: 'REFERENCE',
      containsReferenceData: true,
      sourceConfirmed: false,
      monetaryDataRedacted: false,
    });
  });

  it('reports an empty anchor only when neither cycle nor statement exists', () => {
    expect(buildPayrollSelfServiceModel(workspace({ nextCycle: null })).empty).toBe(true);
    expect(
      buildPayrollSelfServiceModel(workspace({ nextCycle: null, statements: [statement()] })).empty
    ).toBe(false);
  });

  it('projects only declared cycle fields and does not retain source objects or sensitive extras', () => {
    const source = workspace();
    const cycle = { ...source.nextCycle!, bankAccount: 'must-not-reach-ui', grossAmount: 12345 };
    const model = buildPayrollSelfServiceModel({ ...source, nextCycle: cycle });

    expect(model.nextCycle).not.toBe(cycle);
    expect(model.nextCycle).toEqual(source.nextCycle);
    expect(model.nextCycle).not.toHaveProperty('bankAccount');
    expect(model.nextCycle).not.toHaveProperty('grossAmount');
    cycle.name = 'Changed source after projection';
    expect(model.nextCycle?.name).toBe('September payroll');
  });
});

describe('pay statement availability', () => {
  it.each([
    [' available ', 'AVAILABLE'],
    ['PENDING', 'PENDING'],
    ['withheld', 'WITHHELD'],
    ['RETIRED', 'RETIRED'],
    ['PUBLISHED', 'UNKNOWN'],
    ['', 'UNKNOWN'],
  ] as const)('normalizes %j conservatively to %s', (source, expected) => {
    expect(normalizePayrollStatementAvailability(source)).toBe(expected);
  });

  it('requires both AVAILABLE state and the source download flag', () => {
    expect(toPayrollStatementModel(statement()).access).toBe('DOWNLOADABLE');
    expect(toPayrollStatementModel(statement({ downloadable: false })).access).toBe(
      'DOWNLOAD_NOT_GRANTED'
    );
    expect(
      toPayrollStatementModel(statement({ availabilityState: 'WITHHELD', downloadable: true }))
    ).toMatchObject({
      availability: 'WITHHELD',
      sourceAvailability: 'WITHHELD',
      sourceDownloadable: false,
      access: 'NOT_AVAILABLE',
    });
  });

  it('preserves an unknown source value for truthful display', () => {
    expect(
      toPayrollStatementModel(statement({ availabilityState: 'SOURCE_DELAYED' }))
    ).toMatchObject({
      availability: 'UNKNOWN',
      sourceAvailability: 'SOURCE_DELAYED',
      sourceDownloadable: false,
    });
  });
});

