import { API_URL } from './env';
import { HttpError, HttpTransportError } from './http-error';
import { getTenantId } from './tenant-util';
import { resolveRequestLocale } from './locale-preference';

type AxiosLikeResponse<T> = { data: T; headers?: Headers };
export type SessionEffect = 'authoritative' | 'neutral';
type RequestConfig = {
  headers?: Record<string, string>;
  responseType?: 'json' | 'blob';
  timeoutMs?: number;
  signal?: AbortSignal;
  keepalive?: boolean;
  contextScopeKey?: string;
};

export type EventStreamMessage = {
  event: string;
  data: unknown;
};

export type EventStreamConfig = {
  signal?: AbortSignal;
  timeoutMs?: number;
  headers?: Record<string, string>;
  contextScopeKey?: string;
  sessionEffect?: SessionEffect;
  onOpen?: () => void;
  onMessage: (message: EventStreamMessage) => void;
};

type CsrfTokenData = {
  token: string;
  headerName: string;
};

type UnauthorizedHandler = (status: number) => void;
type UnauthorizedHandlerRegistration = Readonly<{
  handler: UnauthorizedHandler;
}>;
export type AuthorizationAccessFailure = Readonly<{
  status: 403 | 409 | 503;
  reasonCode?: string;
  contextScopeKey?: string;
  rejectedDecisionRevision?: string;
  serverDecisionRevision?: string;
}>;
type AuthorizationAccessFailureHandler = (
  failure: AuthorizationAccessFailure
) => void | Promise<void>;
type AuthorizationAccessFailureRegistration = Readonly<{
  handler: AuthorizationAccessFailureHandler;
}>;
let unauthorizedHandlerRegistration: UnauthorizedHandlerRegistration | null = null;
let authorizationAccessFailureRegistration: AuthorizationAccessFailureRegistration | null = null;
let csrfToken: CsrfTokenData | null = null;
let csrfTokenPromise: Promise<CsrfTokenData> | null = null;

export function setUnauthorizedHandler(handler: UnauthorizedHandler | null): () => void {
  const registration = handler ? { handler } : null;
  unauthorizedHandlerRegistration = registration;
  return () => {
    if (unauthorizedHandlerRegistration === registration) {
      unauthorizedHandlerRegistration = null;
    }
  };
}

export function setAuthorizationAccessFailureHandler(
  handler: AuthorizationAccessFailureHandler | null
): () => void {
  const registration = handler ? { handler } : null;
  authorizationAccessFailureRegistration = registration;
  return () => {
    if (authorizationAccessFailureRegistration === registration) {
      authorizationAccessFailureRegistration = null;
    }
  };
}

const AUTHORIZATION_CONFLICT_REASONS = new Set([
  'DECISION_REVISION_CONFLICT',
  'SCOPE_CONTEXT_EXPIRED',
]);

function responseReasonCode(payload: unknown): string | undefined {
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return undefined;
  const record = payload as Record<string, unknown>;
  const value = record.errorCode ?? record.reasonCode ?? record.code;
  return typeof value === 'string' && value.trim() ? value.trim().toUpperCase() : undefined;
}

export function classifyAuthorizationAccessFailure(
  status: number,
  payload: unknown
): AuthorizationAccessFailure | null {
  const reasonCode = responseReasonCode(payload);
  // Most 403 responses are authoritative, route-local denials. Scope expiry is the one
  // contractual exception: the server has rejected the issued scope itself, so retaining
  // scope-bound queries would keep revoked data alive past the authority boundary.
  if (status === 403) {
    return reasonCode === 'SCOPE_CONTEXT_EXPIRED' ? { status, reasonCode } : null;
  }
  if (status === 409 && reasonCode && AUTHORIZATION_CONFLICT_REASONS.has(reasonCode)) {
    return { status, reasonCode };
  }
  if (status === 503 && reasonCode === 'AUTHORITY_RESOLUTION_UNAVAILABLE') {
    return { status, reasonCode };
  }
  return null;
}

function requestContextScopeKey(body: unknown, configuredScopeKey?: string): string | undefined {
  if (configuredScopeKey) return configuredScopeKey;
  if (!body || typeof body !== 'object' || Array.isArray(body)) return undefined;
  const value = (body as Record<string, unknown>).contextScopeKey;
  return typeof value === 'string' && value.trim() ? value : undefined;
}

const EXPECTED_DECISION_REVISION_HEADER = 'x-dwp-expected-decision-revision';
const RESPONSE_DECISION_REVISION_HEADER = 'X-DWP-Decision-Revision';

function requestDecisionRevision(headers?: Record<string, string>): string | undefined {
  if (!headers) return undefined;
  const entry = Object.entries(headers).find(
    ([name]) => name.toLowerCase() === EXPECTED_DECISION_REVISION_HEADER
  );
  const value = entry?.[1];
  return typeof value === 'string' && value.trim() ? value.trim() : undefined;
}

function notifyAuthorizationAccessFailure(
  status: number,
  payload: unknown,
  context?: Readonly<{
    contextScopeKey?: string;
    rejectedDecisionRevision?: string;
    serverDecisionRevision?: string;
  }>,
  registration: AuthorizationAccessFailureRegistration | null = authorizationAccessFailureRegistration
): void {
  const failure = classifyAuthorizationAccessFailure(status, payload);
  if (!failure || !registration || authorizationAccessFailureRegistration !== registration) {
    return;
  }
  const contextualFailure = {
    ...failure,
    ...(context?.contextScopeKey ? { contextScopeKey: context.contextScopeKey } : {}),
    ...(context?.rejectedDecisionRevision
      ? { rejectedDecisionRevision: context.rejectedDecisionRevision }
      : {}),
    ...(context?.serverDecisionRevision
      ? { serverDecisionRevision: context.serverDecisionRevision }
      : {}),
  };
  try {
    void Promise.resolve(registration.handler(contextualFailure)).catch(() => undefined);
  } catch {
    // Observing an access failure must never replace the original HTTP failure.
  }
}

function notifyUnauthorized(
  status: number,
  registration: UnauthorizedHandlerRegistration | null
): void {
  if (status !== 401 || !registration || unauthorizedHandlerRegistration !== registration) {
    return;
  }
  try {
    registration.handler(status);
  } catch {
    // Observing a rejected session must never replace the original HTTP failure.
  }
}

export function resetCsrfToken(): void {
  csrfToken = null;
  csrfTokenPromise = null;
}

function buildHeaders(body: unknown, extra?: Record<string, string>): Record<string, string> {
  const headers: Record<string, string> = {
    Accept: 'application/json',
    'X-Tenant-ID': getTenantId(),
    ...extra,
  };
  if (body !== undefined && !isFormData(body) && !isBlob(body)) {
    headers['Content-Type'] = 'application/json';
  }
  if (isBlob(body) && !headers['Content-Type']) {
    headers['Content-Type'] = body.type || 'application/octet-stream';
  }
  headers['Accept-Language'] = resolveRequestLocale();
  return headers;
}

function isFormData(value: unknown): value is FormData {
  return typeof FormData !== 'undefined' && value instanceof FormData;
}

function isBlob(value: unknown): value is Blob {
  return typeof Blob !== 'undefined' && value instanceof Blob;
}

function isMutation(method: string): boolean {
  return !['GET', 'HEAD', 'OPTIONS'].includes(method);
}

function hasControlCharacter(value: string): boolean {
  return Array.from(value).some((character) => {
    const codePoint = character.codePointAt(0) ?? 0;
    return codePoint <= 31 || codePoint === 127;
  });
}

function withContextScope(url: string, contextScopeKey?: string): string {
  if (contextScopeKey === undefined) return url;
  if (
    !contextScopeKey ||
    contextScopeKey !== contextScopeKey.trim() ||
    contextScopeKey.length > 500 ||
    hasControlCharacter(contextScopeKey) ||
    /(?:^|[?&])contextScopeKey(?:=|&|$)/u.test(url) ||
    url.includes('#')
  ) {
    throw new Error('Product surface context scope is invalid.');
  }
  const separator = url.includes('?') ? '&' : '?';
  return `${url}${separator}contextScopeKey=${encodeURIComponent(contextScopeKey)}`;
}

async function parseBody(response: Response, responseType: 'json' | 'blob' = 'json') {
  if (response.status === 204) return undefined;
  if (responseType === 'blob') return response.blob();
  const text = await response.text();
  if (!text) return undefined;
  try {
    return JSON.parse(text);
  } catch {
    return text;
  }
}

async function loadCsrfToken(keepalive = false): Promise<CsrfTokenData> {
  if (csrfToken) return csrfToken;
  if (csrfTokenPromise) return csrfTokenPromise;

  csrfTokenPromise = fetch(API_URL + '/api/auth/csrf', {
    method: 'GET',
    headers: buildHeaders(undefined),
    credentials: 'include',
    keepalive,
  })
    .then(async (response) => {
      const payload = await parseBody(response);
      if (!response.ok) {
        throw new HttpError(
          'CSRF token request failed: ' + response.status,
          response.status,
          payload
        );
      }
      const data = (payload as { data?: Partial<CsrfTokenData> } | null)?.data;
      if (!data || typeof data.token !== 'string' || typeof data.headerName !== 'string') {
        throw new HttpError('CSRF token response is invalid.', response.status, payload);
      }
      csrfToken = { token: data.token, headerName: data.headerName };
      return csrfToken;
    })
    .finally(() => {
      csrfTokenPromise = null;
    });

  return csrfTokenPromise;
}

async function request<T>(
  method: string,
  url: string,
  body?: unknown,
  config: RequestConfig = {},
  sessionEffect: SessionEffect = 'authoritative',
  allowCsrfRetry = true,
  unauthorizedRegistration = sessionEffect === 'authoritative'
    ? unauthorizedHandlerRegistration
    : null,
  accessFailureRegistration = sessionEffect === 'authoritative'
    ? authorizationAccessFailureRegistration
    : null
): Promise<AxiosLikeResponse<T>> {
  const headers = buildHeaders(body, config.headers);
  const scopedUrl = withContextScope(url, config.contextScopeKey);
  if (isMutation(method)) {
    const csrf = await loadCsrfToken(config.keepalive);
    headers[csrf.headerName] = csrf.token;
  }

  const controller = config.timeoutMs || config.signal ? new AbortController() : undefined;
  const abortFromCaller = () => controller?.abort(config.signal?.reason);
  if (config.signal?.aborted) abortFromCaller();
  else config.signal?.addEventListener('abort', abortFromCaller, { once: true });
  let timedOut = false;
  const timeout =
    controller && config.timeoutMs
      ? globalThis.setTimeout(() => {
          timedOut = true;
          controller.abort('request-timeout');
        }, config.timeoutMs)
      : undefined;
  let response: Response;
  try {
    try {
      response = await fetch(API_URL + scopedUrl, {
        method,
        headers,
        credentials: 'include',
        body:
          body === undefined
            ? undefined
            : isFormData(body) || isBlob(body)
              ? body
              : JSON.stringify(body),
        signal: controller?.signal,
        keepalive: config.keepalive,
      });
    } catch (cause) {
      throw new HttpTransportError(
        timedOut ? 'TIMEOUT' : controller?.signal.aborted ? 'ABORT' : 'NETWORK',
        cause
      );
    }
  } finally {
    if (timeout !== undefined) globalThis.clearTimeout(timeout);
    config.signal?.removeEventListener('abort', abortFromCaller);
  }
  const payload = await parseBody(response, response.ok ? config.responseType : 'json');

  if (!response.ok) {
    const csrfRejected = response.status === 403 && isMutation(method) && payload === undefined;
    if (csrfRejected) {
      resetCsrfToken();
      if (allowCsrfRetry) {
        return request<T>(
          method,
          url,
          body,
          config,
          sessionEffect,
          false,
          unauthorizedRegistration,
          accessFailureRegistration
        );
      }
    }
    notifyUnauthorized(response.status, unauthorizedRegistration);
    if (!csrfRejected) {
      notifyAuthorizationAccessFailure(
        response.status,
        payload,
        {
          contextScopeKey: requestContextScopeKey(body, config.contextScopeKey),
          rejectedDecisionRevision: requestDecisionRevision(config.headers),
          serverDecisionRevision:
            response.headers?.get(RESPONSE_DECISION_REVISION_HEADER)?.trim() || undefined,
        },
        accessFailureRegistration
      );
    }
    const record =
      typeof payload === 'object' && payload !== null ? (payload as Record<string, unknown>) : null;
    const message =
      (typeof record?.message === 'string' && record.message) ||
      (typeof record?.error === 'string' && record.error) ||
      'Request failed: ' + response.status;
    throw new HttpError(message, response.status, payload);
  }

  return { data: payload as T, headers: response.headers };
}

function createHttpClient(sessionEffect: SessionEffect) {
  return {
    get: <T>(url: string, config?: RequestConfig) =>
      request<T>('GET', url, undefined, config, sessionEffect),
    post: <T, B = unknown>(url: string, body: B, config?: RequestConfig) =>
      request<T>('POST', url, body, config, sessionEffect),
    put: <T, B = unknown>(url: string, body: B, config?: RequestConfig) =>
      request<T>('PUT', url, body, config, sessionEffect),
    patch: <T, B = unknown>(url: string, body: B, config?: RequestConfig) =>
      request<T>('PATCH', url, body, config, sessionEffect),
    delete: <T>(url: string, config?: RequestConfig) =>
      request<T>('DELETE', url, undefined, config, sessionEffect),
  };
}

export const sessionHttp = createHttpClient('authoritative');
export const sessionNeutralHttp = createHttpClient('neutral');

/** @deprecated Prefer the client whose session effect matches the endpoint contract. */
export const axiosInstance = sessionHttp;

export async function postEventStream<B>(
  url: string,
  body: B,
  config: EventStreamConfig
): Promise<void> {
  return streamRequest('POST', url, body, config, config.sessionEffect ?? 'authoritative', true);
}

export async function getEventStream(url: string, config: EventStreamConfig): Promise<void> {
  return streamRequest(
    'GET',
    url,
    undefined,
    config,
    config.sessionEffect ?? 'authoritative',
    false
  );
}

async function streamRequest<B>(
  method: 'GET' | 'POST',
  url: string,
  body: B | undefined,
  config: EventStreamConfig,
  sessionEffect: SessionEffect,
  allowCsrfRetry: boolean,
  unauthorizedRegistration = sessionEffect === 'authoritative'
    ? unauthorizedHandlerRegistration
    : null,
  accessFailureRegistration = sessionEffect === 'authoritative'
    ? authorizationAccessFailureRegistration
    : null
): Promise<void> {
  const headers = buildHeaders(body, { Accept: 'text/event-stream', ...config.headers });
  const scopedUrl = withContextScope(url, config.contextScopeKey);
  if (isMutation(method)) {
    const csrf = await loadCsrfToken();
    headers[csrf.headerName] = csrf.token;
  }
  const controller = new AbortController();
  const abortFromCaller = () => controller.abort(config.signal?.reason);
  if (config.signal?.aborted) abortFromCaller();
  else config.signal?.addEventListener('abort', abortFromCaller, { once: true });
  const timeout = config.timeoutMs
    ? globalThis.setTimeout(() => controller.abort('request-timeout'), config.timeoutMs)
    : undefined;

  try {
    const response = await fetch(API_URL + scopedUrl, {
      method,
      headers,
      credentials: 'include',
      body: body === undefined ? undefined : JSON.stringify(body),
      signal: controller.signal,
    });
    if (!response.ok) {
      const payload = await parseBody(response);
      if (response.status === 403 && payload === undefined && allowCsrfRetry) {
        resetCsrfToken();
        return streamRequest(
          method,
          url,
          body,
          config,
          sessionEffect,
          false,
          unauthorizedRegistration,
          accessFailureRegistration
        );
      }
      notifyUnauthorized(response.status, unauthorizedRegistration);
      if (!(response.status === 403 && payload === undefined && isMutation(method))) {
        notifyAuthorizationAccessFailure(
          response.status,
          payload,
          {
            contextScopeKey: requestContextScopeKey(body, config.contextScopeKey),
            rejectedDecisionRevision: requestDecisionRevision(config.headers),
            serverDecisionRevision:
              response.headers?.get(RESPONSE_DECISION_REVISION_HEADER)?.trim() || undefined,
          },
          accessFailureRegistration
        );
      }
      throw new HttpError(
        `Event stream request failed: ${response.status}`,
        response.status,
        payload
      );
    }
    if (!response.body) throw new HttpError('Event stream response body is missing.', 502);
    config.onOpen?.();

    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = '';
    while (true) {
      const { done, value } = await reader.read();
      buffer += decoder.decode(value, { stream: !done }).replaceAll('\r\n', '\n');
      const frames = buffer.split('\n\n');
      buffer = frames.pop() ?? '';
      frames.filter(Boolean).forEach((frame) => config.onMessage(parseEventFrame(frame)));
      if (done) break;
    }
    if (buffer.trim()) config.onMessage(parseEventFrame(buffer));
  } finally {
    if (timeout !== undefined) globalThis.clearTimeout(timeout);
    config.signal?.removeEventListener('abort', abortFromCaller);
  }
}

function parseEventFrame(frame: string): EventStreamMessage {
  let event = 'message';
  const data: string[] = [];
  for (const line of frame.split('\n')) {
    if (line.startsWith('event:')) event = line.slice(6).trim();
    if (line.startsWith('data:')) data.push(line.slice(5).trimStart());
  }
  const raw = data.join('\n');
  try {
    return { event, data: raw ? JSON.parse(raw) : null };
  } catch {
    throw new HttpError('Event stream payload is invalid.', 502, raw);
  }
}

export class HttpError extends Error {
  constructor(
    message: string,
    public readonly status: number,
    public readonly details?: unknown
  ) {
    super(message);
    this.name = 'HttpError';
  }
}

export class HttpTransportError extends Error {
  constructor(
    public readonly reason: 'NETWORK' | 'TIMEOUT' | 'ABORT',
    cause?: unknown
  ) {
    super(`HTTP transport failed: ${reason.toLowerCase()}`, { cause });
    this.name = 'HttpTransportError';
  }
}

export type ProductSurfaceReadScopeConfig = Readonly<{
  contextScopeKey?: string;
  signal?: AbortSignal;
}>;

export function productSurfaceReadScopeConfig(
  contextScopeKey?: string,
  signal?: AbortSignal
): ProductSurfaceReadScopeConfig | undefined {
  if (contextScopeKey === undefined && signal === undefined) return undefined;
  return {
    ...(contextScopeKey === undefined ? {} : { contextScopeKey }),
    ...(signal === undefined ? {} : { signal }),
  };
}
